function remainder(n, d) {
    return n < d
           ? n
           : remainder(n - d, d);
}

;

const gcd_elaborated_machine =
    make_machine(
        list("a", "b", "t"),
        list(list("=", (a, b) => a === b),
             list("<", (a, b) => a < b),
             list("-", (a, b) => a - b)),
        controller_sequence(gcd_elaborated_controller));

